import type { CollectionName, Doc, SeedSource } from '../types';

// The seed JSON files are generated by a later task. The path is a template
// literal so TypeScript does not type-check (or require) each module, and the
// bundler turns it into a lazy per-file chunk. A missing module resolves to [].
async function importSeed(name: CollectionName): Promise<unknown> {
  const mod = (await import(/* webpackMode: "lazy" */ `../seed-data/${name}.json`)) as {
    default?: unknown;
  };
  return mod.default ?? mod;
}

export function createSeedSource(): SeedSource {
  return {
    async load(coll: CollectionName): Promise<Doc[]> {
      try {
        const data = await importSeed(coll);
        return Array.isArray(data) ? (data as Doc[]) : [];
      } catch {
        return [];
      }
    },
  };
}
